const product = $('Get Latest Product').item.json;
const keywordRows = $('Get Top Keywords').all();
const keywords = keywordRows.map(r => r.json.keyword).filter(Boolean);
const durationDays = $('Webhook Trigger').item.json.durationDays;
const startDate = new Date().toISOString().split('T')[0];

const prompt = `Kamu adalah content strategist TikTok untuk affiliator Indonesia.
Buat content plan ${durationDays} hari untuk produk berikut:

Produk: ${product.name}
Selling Points: ${(product.selling_points || []).join(', ')}
Target Market: ${product.target_market}
Trending Keywords: ${keywords.join(', ')}
Tanggal Mulai: ${startDate}

Buat ${durationDays} konten, satu per hari. Variasikan jenis konten (Entertain, Softselling, Edukasi, Hardselling, Trend, Problem-Solution).

Output HANYA JSON array (tanpa markdown, tanpa penjelasan):
[{
  "row_number": 1,
  "post_date": "YYYY-MM-DD",
  "title": "judul konten",
  "content_type": "Entertain|Softselling|Edukasi|Hardselling|Trend|Problem-Solution",
  "post_type": "Video TikTok|Video + Story|Story|Live",
  "hook": "kalimat hook pembuka",
  "caption": "caption TikTok (max 200 karakter)",
  "hashtags": ["#tag1", "#tag2", "#tag3", "#tag4", "#tag5"]
}]`;

return [{ json: { prompt, product, durationDays, startDate } }];

